import os
import requests

def extract_layout(payload, config=None):
    config = config or {}
    headers = {
        'Content-Type': 'application/json',
        'Ocp-Apim-Subscription-Key': os.getenv('AZURE_COMPUTER_VISION_SUBSCRIPTION_KEY')
    }
    data = {
        'image': payload
    }
    response = requests.post(
        'https://<REGION>.cognitiveservices.azure.com/vision/v3.2/layout/read',
        headers=headers,
        json=data
    )
    result = response.json()
    return result

